<template>
  <div v-if="auth.role === 'student'" class="stack"><div class="toolbar page-toolbar activity-toolbar"><strong class="cell-primary">{{ activity?.title || 'Không gian làm bài' }}</strong><div class="toolbar-actions"><button class="button ghost" v-if="attempt && !submitted && !expired" @click="toggleIdle">{{ isIdle ? 'Tiếp tục' : 'Tạm dừng' }}</button><button class="button secondary" v-if="attempt && !submitted && !interactionBlocked" @click="toggleHelp">{{ attempt.helpRequested ? 'Hủy yêu cầu' : 'Cần hỗ trợ' }}</button><button class="button danger" :disabled="!attempt || saving || submitted || interactionBlocked" @click="submitAttempt">Nộp bài</button></div></div><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><div v-if="loading" class="loading-state">Đang tải hoạt động…</div><template v-else-if="activity"><section v-if="!attempt" class="panel empty-state"><strong>Bạn chưa bắt đầu hoạt động</strong><span>Nhấn bắt đầu để tạo lần làm bài của riêng bạn.</span><button class="button primary" @click="startAttempt">Bắt đầu</button></section><div v-if="attempt && interactionMessage" class="save-state" role="status">{{ interactionMessage }}</div><StudentAttemptWorkspace
  v-if="attempt"
  mode="interactive"
  :activity="activity"
  :attempt="attempt"
  :saving="saving || openingQuestion"
  :submitted="submitted || interactionBlocked"
  :save-message="saveMessage"
  @open-question="openQuestion"
  @select-answer="handleAnswerSelected"
/></template></div>
  <div v-else class="stack"><div class="toolbar page-toolbar activity-toolbar"><strong class="cell-primary">{{ activity?.title || 'Không gian làm bài' }}</strong><div class="toolbar-actions"><button v-if="activity && isDraftActivity && sessionId" class="button primary" @click="publishInSession">Phát hành trong phiên</button><RouterLink class="button secondary" to="/activities">Quay lại danh sách</RouterLink></div></div><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><div v-if="loading" class="loading-state">Đang tải tổng quan…</div><template v-else-if="activity"><section class="panel teacher-overview-panel"><div class="panel-heading"><div><h2>Tổng quan lớp học</h2><span>Chọn một lần làm bài để mở không gian làm bài của sinh viên theo thời gian thực.</span></div><span>{{ overview?.students.length || 0 }} người học</span></div><form v-if="activity.status === 0 || String(activity.status).toLowerCase() === 'draft'" class="inline-form" style="margin-bottom:15px" @submit.prevent="addQuestionToActivity"><div class="form-field"><label>Thêm phiên bản câu hỏi</label><select v-model="questionForm.versionId" class="form-select" required><option value="">Chọn từ ngân hàng câu hỏi</option><option v-for="item in questionVersions" :key="item.id" :value="item.id">{{ item.topic }} · v{{ item.version }} · {{ item.prompt }}</option></select></div><div class="form-field" style="max-width:100px"><label>Điểm</label><input v-model.number="questionForm.points" class="form-input" type="number" min="0.1" step="0.1" /></div><button class="button primary" :disabled="addingQuestion">Thêm câu</button></form><div v-if="overview?.students.length" class="table-wrap"><table class="data-table"><thead><tr><th>Học viên</th><th>Tiến độ</th><th>Trạng thái</th><th>Hỗ trợ</th><th></th></tr></thead><tbody><tr v-for="student in overview.students" :key="student.attemptId || student.studentId"><td><span class="cell-primary">{{ student.studentId.slice(0, 8) }}</span><span class="cell-subtle">Câu {{ student.currentQuestionId ? questionNumber(student.currentQuestionId) : '—' }}</span></td><td><div class="progress-track"><div class="progress-fill" :style="{ width: `${student.progress}%` }"></div></div><span class="cell-subtle">{{ student.answeredCount }}/{{ student.totalQuestions }} · {{ student.progress }}%</span></td><td><StatusPill :value="student.status ?? 'Not started'" :labels="['Đang làm bài', 'Không hoạt động', 'Tạm dừng', 'Đã nộp', 'Đã đóng']" /></td><td><span :class="student.helpRequested ? 'status-pill danger' : 'status-pill muted'">{{ student.helpRequested ? 'Cần hỗ trợ' : '—' }}</span></td><td><RouterLink v-if="student.attemptId && student.attemptId !== emptyGuid" class="mini-button" :to="`/activities/${activity.id}/attempts/${student.attemptId}`">Mở không gian làm bài</RouterLink><span v-else class="cell-subtle">Chưa bắt đầu</span></td></tr></tbody></table></div><div v-else class="empty-state"><strong>Chưa có dữ liệu tổng quan</strong><span>Tổng quan sẽ có dữ liệu sau khi người học bắt đầu hoạt động.</span></div></section><section class="panel rubric-panel" style="margin-top:16px"><div class="panel-heading"><div><h2>Tiêu chí chấm điểm</h2><span>Tiêu chí dùng khi chấm câu tự luận của hoạt động.</span></div><span v-if="rubric?.updatedAt">Cập nhật {{ formatDateTime(rubric.updatedAt) }}</span></div><div v-if="rubricCriteria.length" class="rubric-criteria"><div v-for="(criterion, index) in rubricCriteria" :key="criterion.id" class="rubric-criterion"><div class="form-field"><label>Tên tiêu chí {{ index + 1 }}</label><input v-model.trim="criterion.name" class="form-input" maxlength="200" /></div><div class="form-field"><label>Điểm tối đa</label><input v-model.number="criterion.maxPoints" class="form-input" type="number" min="0.1" step="0.1" /></div><div class="form-field rubric-description"><label>Mô tả</label><input v-model.trim="criterion.description" class="form-input" maxlength="4000" /></div><button class="mini-button" type="button" @click="removeCriterion(index)">Xóa</button></div></div><div v-else class="empty-state"><strong>Chưa có tiêu chí</strong><span>Thêm tiêu chí để giảng viên chấm nhất quán.</span></div><div class="card-actions"><button class="mini-button" type="button" @click="addCriterion">Thêm tiêu chí</button><button class="button primary" type="button" :disabled="rubricBusy || !rubricCriteria.length" @click="saveRubric">{{ rubricBusy ? 'Đang lưu…' : 'Lưu tiêu chí' }}</button><span v-if="rubricMessage" class="save-state">{{ rubricMessage }}</span></div></section><section class="panel" style="margin-top:16px"><div class="panel-heading"><h2>Hàng đợi hỗ trợ</h2><span>{{ helpRequests.length }} yêu cầu</span></div><div v-if="helpRequests.length" class="list-compact"><div v-for="request in helpRequests" :key="request.attemptId" class="list-compact-item"><div><strong>{{ request.studentId.slice(0, 8) }}</strong><span>{{ request.activityTitle }} · {{ request.requestedAt ? formatDateTime(request.requestedAt) : '—' }}</span></div><div class="card-actions"><StatusPill :value="request.helpStatus" /><button class="mini-button" @click="acknowledge(request)">Đã tiếp nhận</button><button class="mini-button" @click="resolve(request)">Đã xử lý</button></div></div></div><div v-else class="empty-state"><strong>Hàng đợi hỗ trợ trống</strong><span>Yêu cầu hỗ trợ sẽ xuất hiện mà không ảnh hưởng đến luồng làm bài.</span></div></section></template></div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'; import { HubConnectionBuilder, LogLevel, type HubConnection } from '@microsoft/signalr'; import { useRoute } from 'vue-router'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import StudentAttemptWorkspace from '../components/StudentAttemptWorkspace.vue'; import { assessmentApi, assessmentManagementApi, gradingApi } from '../../../shared/api/client'; import { errorMessage } from '../../../shared/api/http'; import { formatDateTime, type AssessmentActivity, type ClassOverview, type OverviewStudent, type StudentActivity, type StudentDetail } from '../../../shared/types'; import { useAuthStore } from '../../../shared/stores/auth'; import { useNavigationStore } from '../../../shared/stores/navigation'; import { stableSubmissionId } from '../../../shared/utils/id'
type HelpRequest = { attemptId: string; studentId: string; activityTitle: string; requestedAt?: string; helpStatus?: string | number }; type QuestionVersionOption = { id: string; version: number; prompt: string; topic: string }
type RubricCriterion = { id: string; name: string; description: string; maxPoints: number; order: number }
type RubricResponse = { id: string; activityId: string; criteria: RubricCriterion[]; updatedAt?: string }
type GradeAdjustment = { id: string; previousScore: number; newScore: number; maxScore: number; reason: string; adjustedAt: string; gradeVersion: number }
const route = useRoute(); const auth = useAuthStore(); const navigation = useNavigationStore(); const activity = ref<AssessmentActivity | null>(null); const attempt = ref<StudentActivity | null>(null); const overview = ref<ClassOverview | null>(null); const helpRequests = ref<HelpRequest[]>([]); const questionVersions = ref<QuestionVersionOption[]>([]); const questionForm = ref({ versionId: '', points: 1 }); const addingQuestion = ref(false); const selectedDetail = ref<StudentDetail | null>(null); const selectedAttemptId = ref(''); const currentIndex = ref(0); const answer = ref(''); const loading = ref(true); const saving = ref(false); const submitted = ref(false); const error = ref(''); const saveMessage = ref(''); const connection = ref<HubConnection | null>(null); const detailRequest = ref(0); const gradeInputs = ref<Record<string, number | undefined>>({}); const gradeRubricIds = ref<Record<string, string>>({}); const gradeFeedback = ref(''); const gradeEntryId = ref(''); const gradeStatus = ref<string | number>(''); const gradeScore = ref(0); const gradeMaxScore = ref(0); const gradingBusy = ref(false); const gradeMessage = ref(''); const rubric = ref<RubricResponse | null>(null); const rubricCriteria = ref<RubricCriterion[]>([]); const rubricBusy = ref(false); const rubricMessage = ref(''); const adjustmentScore = ref<number | undefined>(undefined); const adjustmentFeedback = ref(''); const adjustmentReason = ref(''); const adjustments = ref<GradeAdjustment[]>([]); const adjustmentBusy = ref(false); const emptyGuid = '00000000-0000-0000-0000-000000000000'
const orderedQuestions = computed(() => { if (!activity.value || !attempt.value?.questionOrder?.length) return activity.value?.questions || []; const byId = new Map(activity.value.questions.map(item => [item.id, item])); return attempt.value.questionOrder.map(id => byId.get(id)).filter(Boolean) as AssessmentActivity['questions'] }); const currentQuestion = computed(() => orderedQuestions.value[currentIndex.value]); const progress = computed(() => attempt.value ? Math.round(attempt.value.answeredCount / Math.max(1, activity.value?.questions.length || 1) * 100) : 0)
const openingQuestion = ref(false)
const clockNow = ref(Date.now())
const clockTimer = setInterval(() => { clockNow.value = Date.now() }, 1000)
onBeforeUnmount(() => clearInterval(clockTimer))
const expired = computed(() => Boolean(attempt.value?.expiresAt && clockNow.value > Date.parse(attempt.value.expiresAt)))
const interactionBlocked = computed(() => expired.value || attempt.value?.canInteract === false)
const interactionMessage = computed(() => expired.value ? 'Đã hết thời gian làm bài. Bạn có thể xem lại câu trả lời đã lưu.' : attempt.value?.interactionMessage || '')
const isIdle = computed(() => attempt.value?.status === 1 || String(attempt.value?.status || '').toLowerCase().includes('idle'))
const sessionId = computed(() => typeof route.query.sessionId === 'string' ? route.query.sessionId : '')
const isDraftActivity = computed(() => Boolean(activity.value && (activity.value.status === 0 || String(activity.value.status).toLowerCase() === 'draft')))
function isPublishedGrade(status: string | number | undefined) { return status === 1 || String(status || '').toLowerCase() === 'published' }
const subjectiveQuestions = computed(() => activity.value?.questions.filter(question => {
  const type = typeof question.type === 'number' ? question.type : String(question.type).toLowerCase()
  return !(type === 0 || type === 1 || type === 2 || type === 'singlechoice' || type === 'multiplechoice' || type === 'truefalse')
}) || [])
function questionNumber(id: string) { return activity.value?.questions.find(item => item.id === id)?.order || '—' }
async function publishInSession() { if (!activity.value || !sessionId.value) return; try { activity.value = await assessmentApi.publishInSession(sessionId.value, activity.value.id); overview.value = await assessmentApi.overview(activity.value.learningClassId, activity.value.id) } catch (cause) { error.value = errorMessage(cause) || 'Không phát hành được hoạt động trong phiên.' } }
async function load() { loading.value = true; error.value = ''; try { activity.value = await assessmentApi.activity(String(route.params.activityId)); navigation.renameTab(route.fullPath, activity.value.title); if (auth.role === 'student') { try { attempt.value = await assessmentApi.attempt(activity.value.id) } catch { attempt.value = null } if (attempt.value) { submitted.value = attempt.value.status === 3 || String(attempt.value.status).toLowerCase() === 'submitted' || String(attempt.value.status).toLowerCase() === 'closed'; syncQuestion() } } else { overview.value = await assessmentApi.overview(activity.value.learningClassId, activity.value.id); helpRequests.value = await assessmentManagementApi.helpRequests(activity.value.learningClassId) as HelpRequest[]; try { const currentRubric = await assessmentManagementApi.rubric(activity.value.id) as RubricResponse; rubric.value = currentRubric; rubricCriteria.value = currentRubric.criteria.map((criterion, index) => ({ ...criterion, order: index })) } catch { rubric.value = null; rubricCriteria.value = [] } const bank = await assessmentApi.questionBank(); const details = await Promise.allSettled((bank as { id: string; topic: string; currentVersion: number }[]).slice(0, 50).map(item => assessmentApi.questionBankDetail(item.id))); questionVersions.value = details.flatMap(result => result.status === 'fulfilled' ? result.value.versions.map(version => ({ id: version.id, version: version.version, prompt: version.prompt, topic: result.value.item.topic })) : []); await connectOverview() } } catch (cause) { error.value = errorMessage(cause) || 'Không tải được hoạt động.' } finally { loading.value = false } }
function syncQuestion() { if (!attempt.value || !orderedQuestions.value.length) return; const id = attempt.value.currentQuestionId || orderedQuestions.value[0].id; const index = orderedQuestions.value.findIndex(item => item.id === id); currentIndex.value = index >= 0 ? index : 0; answer.value = attempt.value.answers[id] || '' }
async function startAttempt() { if (!activity.value) return; try { attempt.value = await assessmentApi.startAttempt(activity.value.id); syncQuestion() } catch (cause) { error.value = errorMessage(cause) || 'Không bắt đầu được lần làm bài.' } }
async function toggleIdle() { if (!attempt.value) return; try { attempt.value = await (isIdle.value ? assessmentApi.resumeAttempt(attempt.value.activityId) : assessmentApi.markIdle(attempt.value.activityId)) } catch (cause) { error.value = errorMessage(cause) || 'Không cập nhật được trạng thái.' } }
async function toggleHelp() { if (!attempt.value) return; try { attempt.value = await (attempt.value.helpRequested ? assessmentApi.withdrawHelp(attempt.value.activityId) : assessmentApi.requestHelp(attempt.value.activityId)) } catch (cause) { error.value = errorMessage(cause) || 'Không cập nhật được yêu cầu hỗ trợ.' } }
async function addQuestionToActivity() { if (!activity.value || !questionForm.value.versionId) return; addingQuestion.value = true; try { activity.value = await assessmentApi.addQuestion(activity.value.id, { questionVersionId: questionForm.value.versionId, order: activity.value.questions.length, points: questionForm.value.points }); overview.value = await assessmentApi.overview(activity.value.learningClassId, activity.value.id); questionForm.value.versionId = '' } catch (cause) { error.value = errorMessage(cause) || 'Không thêm được câu hỏi.' } finally { addingQuestion.value = false } }
type GradeEntrySnapshot = { id: string; score: number; maxScore: number; feedback?: string; questionResults?: { questionId: string; score: number; rubricCriterionId?: string }[]; status?: string | number }
function resetGradeForm() { gradeInputs.value = {}; gradeRubricIds.value = {}; gradeFeedback.value = ''; gradeEntryId.value = ''; gradeStatus.value = ''; gradeScore.value = 0; gradeMaxScore.value = 0; adjustments.value = []; adjustmentScore.value = undefined; adjustmentFeedback.value = ''; adjustmentReason.value = ''; gradeMessage.value = '' }
async function loadExistingGrade(detail: StudentDetail, requestId: number) {
  resetGradeForm()
  if (!activity.value) return
  try {
    const submissionId = await stableSubmissionId(activity.value.id, detail.studentId, detail.attemptNumber || 1)
    const entry = await gradingApi.getGradeEntry(submissionId) as GradeEntrySnapshot
    if (requestId !== detailRequest.value) return
    gradeEntryId.value = entry.id
    gradeStatus.value = entry.status || 'Draft'
    gradeScore.value = Number(entry.score || 0)
    gradeMaxScore.value = Number(entry.maxScore || 0)
    adjustmentScore.value = gradeScore.value
    adjustmentFeedback.value = entry.feedback || ''
    gradeFeedback.value = entry.feedback || ''
    for (const result of entry.questionResults || []) { gradeInputs.value[result.questionId] = Number(result.score); if (result.rubricCriterionId) gradeRubricIds.value[result.questionId] = result.rubricCriterionId }
  } catch {
    // A missing grade entry is expected until a teacher saves the first draft.
  }
}
function addCriterion() { rubricCriteria.value.push({ id: globalThis.crypto.randomUUID(), name: '', description: '', maxPoints: 1, order: rubricCriteria.value.length }) }
function removeCriterion(index: number) { rubricCriteria.value.splice(index, 1); rubricCriteria.value.forEach((criterion, order) => { criterion.order = order }) }
async function saveRubric() { if (!activity.value || !rubricCriteria.value.length) return; rubricBusy.value = true; rubricMessage.value = 'Đang lưu…'; try { const criteria = rubricCriteria.value.map((criterion, order) => ({ ...criterion, order, maxPoints: Number(criterion.maxPoints) })); rubric.value = await assessmentManagementApi.saveRubric(activity.value.id, criteria) as RubricResponse; rubricCriteria.value = rubric.value.criteria.map((criterion, index) => ({ ...criterion, order: index })); rubricMessage.value = 'Đã lưu tiêu chí'; setTimeout(() => { rubricMessage.value = '' }, 1600) } catch (cause) { rubricMessage.value = errorMessage(cause) || 'Không lưu được tiêu chí.' } finally { rubricBusy.value = false } }
async function loadAdjustments() { if (!gradeEntryId.value) return; try { adjustments.value = await gradingApi.adjustments(gradeEntryId.value) as GradeAdjustment[] } catch (cause) { gradeMessage.value = errorMessage(cause) || 'Không tải được lịch sử điều chỉnh.' } }
async function adjustGrade() { if (!gradeEntryId.value || adjustmentScore.value === undefined) return; if (!adjustmentReason.value.trim()) { gradeMessage.value = 'Lý do điều chỉnh là bắt buộc.'; return } if (adjustmentScore.value < 0 || adjustmentScore.value > gradeMaxScore.value) { gradeMessage.value = 'Điểm điều chỉnh không hợp lệ.'; return } adjustmentBusy.value = true; try { const result = await gradingApi.adjustGrade(gradeEntryId.value, { score: Number(adjustmentScore.value), feedback: adjustmentFeedback.value.trim() || undefined, reason: adjustmentReason.value.trim() }) as GradeEntrySnapshot; gradeStatus.value = result.status || 'Draft'; gradeScore.value = Number(result.score || adjustmentScore.value); gradeFeedback.value = result.feedback || ''; adjustmentReason.value = ''; await loadAdjustments(); gradeMessage.value = 'Đã lưu điều chỉnh. Cần công bố lại điểm.' } catch (cause) { gradeMessage.value = errorMessage(cause) || 'Không điều chỉnh được điểm.' } finally { adjustmentBusy.value = false } }
async function gradeSelectedStudent() {
  if (!activity.value || !selectedDetail.value) return
  const questions = subjectiveQuestions.value.map(question => ({
    questionId: question.id,
    score: Number(gradeInputs.value[question.id]),
    rubricCriterionId: gradeRubricIds.value[question.id] || undefined,
  }))
  if (questions.some(value => !Number.isFinite(value.score) || value.score < 0 || value.score > Number(activity.value?.questions.find(question => question.id === value.questionId)?.points || 0))) {
    gradeMessage.value = 'Nhập điểm hợp lệ cho tất cả câu tự luận.'
    return
  }
  gradingBusy.value = true
  gradeMessage.value = 'Đang lưu…'
  try {
    const submissionId = await stableSubmissionId(activity.value.id, selectedDetail.value.studentId, selectedDetail.value.attemptNumber || 1)
    const result = await gradingApi.gradeSubmission(submissionId, { questions, feedback: gradeFeedback.value.trim() || undefined, rubricId: rubric.value?.id }) as GradeEntrySnapshot
    gradeEntryId.value = result.id
    gradeStatus.value = result.status || 'Draft'
    gradeScore.value = Number(result.score || 0)
    gradeMaxScore.value = Number(result.maxScore || 0)
    adjustmentScore.value = gradeScore.value
    adjustmentFeedback.value = result.feedback || gradeFeedback.value
    gradeMessage.value = `Đã lưu bản chấm · ${Number(result.score).toFixed(1)}/${Number(result.maxScore).toFixed(1)}`
  } catch (cause) {
    gradeMessage.value = errorMessage(cause) || 'Không lưu được bản chấm.'
  } finally {
    gradingBusy.value = false
  }
}
async function publishSelectedGrade() {
  if (!gradeEntryId.value) return
  gradingBusy.value = true
  try {
    const result = await gradingApi.publishGrade(gradeEntryId.value) as GradeEntrySnapshot
    gradeStatus.value = result.status || 'Published'
    gradeScore.value = Number(result.score || gradeScore.value)
    gradeMaxScore.value = Number(result.maxScore || gradeMaxScore.value)
    adjustmentScore.value = gradeScore.value
    adjustmentFeedback.value = result.feedback || gradeFeedback.value
    gradeMessage.value = 'Đã công bố điểm cho sinh viên.'
  } catch (cause) {
    gradeMessage.value = errorMessage(cause) || 'Không công bố được điểm.'
  } finally {
    gradingBusy.value = false
  }
}
let answerSavePromise: Promise<void> | null = null
async function handleAnswerSelected(questionId: string, value: string) { if (!attempt.value || !activity.value || submitted.value) return; const index = orderedQuestions.value.findIndex(question => question.id === questionId); if (index >= 0) currentIndex.value = index; answer.value = value; answerSavePromise = saveCurrentAnswer(); try { await answerSavePromise } finally { answerSavePromise = null } }
async function openQuestion(questionId: string) { if (!attempt.value || !activity.value || openingQuestion.value || interactionBlocked.value) return; openingQuestion.value = true; if (answerSavePromise) await answerSavePromise; const index = orderedQuestions.value.findIndex(question => question.id === questionId); if (index < 0) { openingQuestion.value = false; return }; const question = orderedQuestions.value[index]; try { error.value = ''; attempt.value = await assessmentApi.openQuestion(activity.value.id, question.id); currentIndex.value = index; answer.value = attempt.value.answers[question.id] || '' } catch (cause) { error.value = errorMessage(cause) || 'Không mở được câu hỏi.' } finally { openingQuestion.value = false } }
async function saveCurrentAnswer() { if (!attempt.value || !activity.value || !currentQuestion.value || submitted.value || interactionBlocked.value) return; const value = answer.value.trim(); if (attempt.value.answers[currentQuestion.value.id] === value) return; saving.value = true; saveMessage.value = 'Đang lưu…'; try { attempt.value = await assessmentApi.saveAnswer(activity.value.id, currentQuestion.value.id, value); saveMessage.value = 'Đã lưu'; setTimeout(() => { saveMessage.value = '' }, 1400) } catch (cause) { saveMessage.value = errorMessage(cause) || 'Lưu thất bại'; error.value = saveMessage.value } finally { saving.value = false } }
async function submitAttempt() { if (!activity.value || !attempt.value) return; if (answerSavePromise) await answerSavePromise; else await saveCurrentAnswer(); if (!window.confirm('Bạn đã sẵn sàng nộp bài?')) return; try { attempt.value = await assessmentApi.submitAttempt(activity.value.id); submitted.value = true; saveMessage.value = 'Đã nộp bài' } catch (cause) { error.value = errorMessage(cause) || 'Không nộp được bài.' } }
async function refreshSelectedDetail() { if (!selectedAttemptId.value || !connection.value) return; const requestId = ++detailRequest.value; try { const snapshot = await assessmentApi.detail(selectedAttemptId.value); if (requestId !== detailRequest.value) return; selectedDetail.value = snapshot; await loadExistingGrade(snapshot, requestId); await connection.value.invoke('SubscribeStudentDetail', selectedAttemptId.value) } catch (cause) { if (requestId === detailRequest.value) error.value = errorMessage(cause) || 'Không tải lại được chi tiết bài làm của sinh viên.' } }
async function connectOverview() { if (!activity.value) return; await connection.value?.stop().catch(() => undefined); const hub = new HubConnectionBuilder().withUrl('/hubs/assessment').withAutomaticReconnect().configureLogging(LogLevel.Warning).build(); hub.on('activity-overview-delta', (delta: OverviewStudent) => { if (!overview.value) return; const index = overview.value.students.findIndex(item => item.attemptId === delta.attemptId || item.studentId === delta.studentId); if (index >= 0) overview.value.students[index] = { ...overview.value.students[index], ...delta }; }); hub.on('activity-detail-delta', (delta: { attemptId: string; version: number; changeType: string; questionId?: string; answerValue?: string; currentQuestionId?: string; answeredCount: number; status: string | number; lastActivityAt: string; helpRequested: boolean }) => { const current = selectedDetail.value; if (!current || delta.attemptId !== selectedAttemptId.value || delta.version < current.version) return; const answers = { ...current.answers }; if (delta.questionId && (delta.changeType === 'answer-changed' || delta.changeType === 'answer-submitted')) answers[delta.questionId] = delta.answerValue || ''; selectedDetail.value = { ...current, answers, currentQuestionId: delta.currentQuestionId, answeredCount: delta.answeredCount, status: delta.status, lastActivityAt: delta.lastActivityAt, helpRequested: delta.helpRequested, version: delta.version } }); hub.onreconnected(async () => { await hub.invoke('SubscribeOverview', activity.value!.learningClassId, activity.value!.id).catch(() => undefined); await refreshSelectedDetail() }); try { await hub.start(); await hub.invoke('SubscribeOverview', activity.value.learningClassId, activity.value.id); connection.value = hub } catch { await hub.stop().catch(() => undefined) } }
async function selectStudent(student: OverviewStudent) { if (!student.attemptId || student.attemptId === emptyGuid || !activity.value) return; const requestId = ++detailRequest.value; const old = selectedAttemptId.value; if (old && connection.value) await connection.value.invoke('UnsubscribeStudentDetail', old).catch(() => undefined); selectedAttemptId.value = student.attemptId; selectedDetail.value = null; resetGradeForm(); try { const snapshot = await assessmentApi.detail(student.attemptId); if (requestId !== detailRequest.value) return; selectedDetail.value = snapshot; await loadExistingGrade(snapshot, requestId); if (!connection.value) return; await connection.value.invoke('SubscribeStudentDetail', student.attemptId) } catch (cause) { if (requestId === detailRequest.value) error.value = errorMessage(cause) || 'Không tải được chi tiết bài làm của sinh viên.' } }
async function acknowledge(request: HelpRequest) { try { await assessmentManagementApi.acknowledgeHelp(request.attemptId); request.helpStatus = 'Đã tiếp nhận' } catch (cause) { error.value = errorMessage(cause) || 'Không tiếp nhận được yêu cầu hỗ trợ.' } }; async function resolve(request: HelpRequest) { try { await assessmentManagementApi.resolveHelp(request.attemptId); request.helpStatus = 'Đã xử lý' } catch (cause) { error.value = errorMessage(cause) || 'Không xử lý được yêu cầu hỗ trợ.' } }
onMounted(load); onBeforeUnmount(async () => { if (connection.value) await connection.value.stop().catch(() => undefined) })
</script>
